            new MemberDescriptor("AnyString::DifferentFrom#1", "DifferentFrom", "AnyString", "AnyString", new List<ParameterDescriptor> { new ParameterDescriptor("value", "System.String", "The value the generated string must differ from.") }, "Requires the generated string to differ from value — typically an existing value the test already holds, to exercise an inequality path while preserving the declared shape. Semantically equivalent to Except, including when a value set is in force; the name carries the intent at the call site.", "https://github.com/Reefact/just-dummies#readme"),
            new MemberDescriptor("AnyString::EndingWith#1", "EndingWith", "AnyString", "AnyString", new List<ParameterDescriptor> { new ParameterDescriptor("suffix", "System.String", "The required suffix.") }, "Requires the string to end with suffix. Declared once per generator.", "https://github.com/Reefact/just-dummies#readme"),
            new MemberDescriptor("AnyString::Except#1", "Except", "AnyString", "AnyString", new List<ParameterDescriptor> { new ParameterDescriptor("values", "System.String[]", "The values the generated string must differ from; duplicates are ignored.") }, "Requires the generated string to be none of the supplied values. May be declared several times; the exclusions accumulate. On a shaped string, and unlike the shape constraints, an exclusion is met by a bounded redraw of the constructed layout, so one tight enough to leave the shape unsatisfiable surfaces at Generate as a seed-bearing AnyGenerationException rather than as a declaration-time conflict. On a string drawn from a value set (OneOf) there is nothing to redraw: the excluded values are removed from the set at once, and removing all of them is a conflict here and now. The empty string is a valid value to exclude; a null element is not.", "https://github.com/Reefact/just-dummies#readme"),
            new MemberDescriptor("AnyString::LowerCase#0", "LowerCase", "AnyString", "AnyString", new List<ParameterDescriptor> {  }, "Requires every alphabetic character to be lowercase. Declared once per generator.", "https://github.com/Reefact/just-dummies#readme"),
            new MemberDescriptor("AnyString::NonEmpty#0", "NonEmpty", "AnyString", "AnyString", new List<ParameterDescriptor> {  }, "Requires at least one character.", "https://github.com/Reefact/just-dummies#readme"),
            new MemberDescriptor("AnyString::Numeric#0", "Numeric", "AnyString", "AnyString", new List<ParameterDescriptor> {  }, "Restricts the string to ASCII digits only. Declared once per generator.", "https://github.com/Reefact/just-dummies#readme"),
            new MemberDescriptor("AnyString::OneOf#1", "OneOf", "AnyString", "AnyString", new List<ParameterDescriptor> { new ParameterDescriptor("values", "System.String[]", "The values the generated string is drawn from; duplicates are ignored.") }, "Draws the string from an explicit, fixed set of values instead of shaping one — the dummy for a value whose domain is a closed list the test does not assert on (a currency code, a well-known name). Declared once per generator, and composable like every other family's OneOf: the other constraints keep their meaning and narrow the set rather than shaping a string, so OneOf(\"abc\", \"de\").WithLength(3) yields \"abc\". A constraint no supplied value satisfies is a ConflictingAnyConstraintException naming both sides, whichever order the two were declared in. Duplicate values are collapsed; the generated string is one of the surviving values, drawn uniformly and reproducibly under a seed.", "https://github.com/Reefact/just-dummies#readme"),
            new MemberDescriptor("AnyString::OrNull", "OrNull", "AnyString", "", new List<ParameterDescriptor> {  }, "", "", PlaygroundSupport.UnavailableInPlayground),
            new MemberDescriptor("AnyString::StartingWith#1", "StartingWith", "AnyString", "AnyString", new List<ParameterDescriptor> { new ParameterDescriptor("prefix", "System.String", "The required prefix.") }, "Requires the string to start with prefix. Declared once per generator.", "https://github.com/Reefact/just-dummies#readme"),
            new MemberDescriptor("AnyString::UpperCase#0", "UpperCase", "AnyString", "AnyString", new List<ParameterDescriptor> {  }, "Requires every alphabetic character to be uppercase. Declared once per generator.", "https://github.com/Reefact/just-dummies#readme"),
            new MemberDescriptor("AnyString::WithChars#1", "WithChars", "AnyString", "AnyString", new List<ParameterDescriptor> { new ParameterDescriptor("pool", "System.String", "The characters the generated string is drawn from; duplicates are ignored.") }, "Restricts the string to the characters of an explicit pool — a custom alphabet, the general form of Alpha/Numeric/AlphaNumeric. Use it to reach characters the named sets cannot, most notably non-ASCII text (accents, other scripts), without a StringMatching literal. Declared once per generator: it occupies the same character-family slot as the named sets, and because the pool is the whole character definition it cannot combine with LowerCase/UpperCase — put only the casing you want in the pool. Any anchored fragment (prefix, suffix, contained value) must be drawn from the pool, otherwise the conflict is reported at declaration naming both sides. Duplicate characters collapse and each distinct character is equally likely. The pool is a sequence of UTF-16 code units and must stay within the Basic Multilingual Plane: a surrogate — an emoji or other astral code point, which spans two units — is rejected, because it would be drawn and split unit by unit; draw such values as whole strings with OneOf instead.", "https://github.com/Reefact/just-dummies#readme"),
            new MemberDescriptor("AnyString::WithLength#1", "WithLength", "AnyString", "AnyString", new List<ParameterDescriptor> { new ParameterDescriptor("length", "System.Int32", "The exact number of characters.") }, "Fixes the exact length. Declared once per generator.", "https://github.com/Reefact/just-dummies#readme"),
            new MemberDescriptor("AnyString::WithLengthBetween#2", "WithLengthBetween", "AnyString", "AnyString", new List<ParameterDescriptor> { new ParameterDescriptor("minimum", "System.Int32", "The inclusive minimum number of characters."), new ParameterDescriptor("maximum", "System.Int32", "The inclusive maximum number of characters.") }, "Requires a length within the inclusive range [minimum, maximum]. Equivalent to declaring the two bounds separately, and behaves as they do: the minimum sets the size, the maximum only caps it. A range whose minimum is 0 therefore yields the default spread, not values spread across the whole range — raise minimum to ask for larger strings.", "https://github.com/Reefact/just-dummies#readme"),
            new MemberDescriptor("AnyString::WithMaxLength#1", "WithMaxLength", "AnyString", "AnyString", new List<ParameterDescriptor> { new ParameterDescriptor("length", "System.Int32", "The inclusive maximum number of characters.") }, "Requires at most length characters. A maximum only ever narrows the draw: it never widens it beyond the default spread, so a loose cap still yields the small unconstrained string rather than one sized after the cap. Any non-negative value is accepted, since nothing has to be produced to honour it.", "https://github.com/Reefact/just-dummies#readme"),
            new MemberDescriptor("AnyString::WithMinLength#1", "WithMinLength", "AnyString", "AnyString", new List<ParameterDescriptor> { new ParameterDescriptor("length", "System.Int32", "The inclusive minimum number of characters.") }, "Requires at least length characters. A minimum is the only one-sided length bound that enlarges the generated string: the draw spans length to length plus the default spread.", "https://github.com/Reefact/just-dummies#readme"),
            new MemberDescriptor("AnyString::Generate#0", "Generate", "AnyString", "Terminal:System.String", new List<ParameterDescriptor> {  }, "Produces one arbitrary value satisfying every constraint declared on this generator.", "https://github.com/Reefact/just-dummies#readme"),
        },
